import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

const val K = 1010
const val MOD = 1_000_000_007

fun powmod(a: Int, x: Int): Int {
    if (x == 0) return 1
    if (x % 2 == 0) return powmod((a.toLong() * a % MOD).toInt(), x / 2)
    return (a.toLong() * powmod(a, x - 1) % MOD).toInt()
}

val dp = Array(K) { IntArray(K) }

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val k = st.nextToken().toInt()
    val va = st.nextToken().toInt()
    val vb = st.nextToken().toInt()

    val den = powmod(va + vb, MOD - 2)
    val pa = (va.toLong() * den % MOD).toInt()
    val pb = (vb.toLong() * den % MOD).toInt()
    val oneB = (pa.toLong() * powmod(pb, MOD - 2) % MOD).toInt()

    for (i in k - 1 downTo 0) {
        for (j in k downTo 1) {
            if (i + j >= k) {
                dp[i][j] = ((i + j + oneB) % MOD)
            } else {
                dp[i][j] = ((pa.toLong() * dp[i][j + 1] + pb.toLong() * dp[i + j][j]) % MOD).toInt()
            }
        }
    }
    println(dp[0][1])
}
